# owner: platform
"""Tests for seating rows."""

import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

# ---
def make_student(last_name, first_name):
    return Student("0", last_name, first_name, "A")

class SeatRowsTests(unittest.TestCase):
    def test_rows_sorted_by_last_name(self):
        students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet")
        ]
        self.assertEqual(
            seat_rows(students, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno"]
        )

    def test_last_row_may_be_partial(self):
        students = [
            make_student("Baker", "Bo"),
            make_student("Moss", "Cy"),
            make_student("Adams", "Ann")
        ]
        expected = [
            "Row 1: Adams, Ann | Baker, Bo",
            "Row 2: Moss, Cy"
        ]
        self.assertEqual(seat_rows(students, 2), expected)

    def test_zero_seats_raises(self):
        students = [make_student("Adams", "Ann")]
        with self.assertRaises(ValueError):
            seat_rows(students, 0)

    def test_negative_seats_raises(self):
        students = [make_student("Adams", "Ann")]
        with self.assertRaises(ValueError):
            seat_rows(students, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
